css:
/* A sangria de -5vw no trilho fura a coluna de propósito, e quem corta o
   excesso é esta seção. Sem o clip, o componente solto numa página cria barra
   de rolagem horizontal no documento inteiro — 'clip' e não 'hidden' porque
   hidden transformaria a seção num container rolável e quebraria position
   sticky de qualquer filho. */
.tr { padding: 40px 0; overflow-x: clip; }
.tr-topo {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 0 40px; margin-bottom: 20px;
}
.tr-titulo { margin: 0; font-family: 'Sora', sans-serif; font-size: 22px; font-weight: 700; }

.tr-setas { display: flex; gap: 8px; }
.tr-seta {
  width: 36px; height: 36px; border: 1px solid var(--border); border-radius: 100px;
  background: transparent; color: var(--text); font-size: 18px; line-height: 1; cursor: pointer;
}
.tr-seta:hover:not(:disabled) { border-color: var(--accent); color: var(--accent); }
.tr-seta:disabled { opacity: 0.3; cursor: default; }

.tr-trilho {
  display: flex; gap: 16px;
  overflow-x: auto;
  /* proximity e NÃO mandatory: com mandatory o navegador reancora a rolagem
     da seta no encaixe mais próximo do início e a fileira volta pro começo. */
  scroll-snap-type: x proximity;
  scroll-behavior: smooth;
  scrollbar-width: none;
  padding: 0 40px;
}
.tr-trilho::-webkit-scrollbar { display: none; }

@media (max-width: 1023px) {
  .tr-trilho {
    /* As três juntas: sem a terceira, o encaixe nasce na borda do container,
       ignora o padding, e o primeiro card desalinha da coluna de texto. */
    padding-inline: 5vw;
    margin-inline: -5vw;
    scroll-padding-inline: 5vw;
  }
  .tr-topo { padding: 0 5vw; }
}

.tr-card {
  flex: 0 0 auto; width: 240px;
  scroll-snap-align: start;
  border: 1px solid var(--border); border-radius: 12px; overflow: hidden;
  background: var(--bg-alt);
}
.tr-foto {
  aspect-ratio: 4 / 5;
  background: linear-gradient(140deg, var(--border-alt), var(--bg));
}
.tr-card h3 { margin: 0; padding: 14px 16px 4px; font-size: 14px; font-family: 'Sora', sans-serif; }
.tr-card p { margin: 0; padding: 0 16px 16px; font-size: 12px; color: var(--text-muted); }

js:
export function iniciarTrilho(raiz) {
  const trilho = raiz.querySelector('.tr-trilho')
  const setas = [...raiz.querySelectorAll('.tr-seta')]

  function passo() {
    const card = trilho.querySelector('.tr-card')
    if (!card) return trilho.clientWidth
    const largura = card.getBoundingClientRect().width + 16
    // Uma página de cards visíveis, não um card: com muitos cards estreitos,
    // avançar de um em um faz a seta parecer quebrada.
    return Math.max(largura, Math.floor(trilho.clientWidth / largura) * largura)
  }

  function atualizar() {
    const fim = trilho.scrollWidth - trilho.clientWidth
    // Tolerância de 2px: largura fracionária faz scrollLeft nunca bater no
    // máximo teórico, e sem a folga a seta da direita nunca desabilita.
    setas[0].disabled = trilho.scrollLeft <= 2
    setas[1].disabled = trilho.scrollLeft >= fim - 2
  }

  setas.forEach((s) => {
    s.addEventListener('click', () => {
      trilho.scrollBy({ left: passo() * Number(s.dataset.dir), behavior: 'smooth' })
    })
  })

  trilho.addEventListener('scroll', atualizar, { passive: true })
  window.addEventListener('resize', atualizar)
  atualizar()
}
